@prefix holon: <https://example.org/holon#> .
@prefix oe: <https://example.org/openevidence#> .
@prefix oeq: <https://example.org/openevidence/questions/> .
@prefix oegen: <https://example.org/openevidence/generated/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<https://example.org/openevidence/questions/q_cellulitis_treatment> a holon:clinicalQuestion ;
  holon:hasAnswer [
    a holon:answer ;
    holon:hasEvidence [
      a holon:evidence ;
      oe:hasDrug <https://example.org/openevidence/drugs/amoxicillin> ;
      oe:treats <https://example.org/openevidence/diseases/cellulitis> ;
      oe:confidence 0.91 ;
      oe:level "Level-1B" ;
      oe:source <https://example.org/openevidence/sources/36402160> ;
      oe:effectiveness "effective"
    ]
  ] .
